#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstdio>
using namespace std;

typedef long long ll;

const int INF = 0x7f7f7f7f;
const int MAX_NODES = 5010000;
const int MOD = 1000000007;

struct Edge {
    int to, capacity, cost, next;
};

vector<Edge> edgeList;
vector<int> nodeHead;

inline void addEdge(int u, int v, int cap, int cost) {
    edgeList.push_back({v, cap, cost, nodeHead[u]});
    nodeHead[u] = edgeList.size() - 1;
    edgeList.push_back({u, 0, -cost, nodeHead[v]});
    nodeHead[v] = edgeList.size() - 1;
}

inline void readInt(int &x) {
    x = 0;
    char c = getchar();
    while (c < '0' || c > '9') {
        if (c == '-') break;
        c = getchar();
    }
    bool neg = false;
    if (c == '-') {
        neg = true;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    if (neg) x = -x;
}

inline void writeInt(int x) {
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    if (x > 9) writeInt(x / 10);
    putchar(x % 10 + '0');
}

inline void writeln(int x) {
    writeInt(x);
    putchar('\n');
}

int sourceNode, sinkNode;
vector<int> distance, minFlow, parentVertex, parentEdge;
vector<bool> inQueue;

bool spfa() {
    fill(distance.begin(), distance.end(), INF);
    fill(minFlow.begin(), minFlow.end(), 0);
    fill(parentVertex.begin(), parentVertex.end(), -1);
    fill(parentEdge.begin(), parentEdge.end(), -1);
    fill(inQueue.begin(), inQueue.end(), false);

    queue<int> q;
    distance[sourceNode] = 0;
    minFlow[sourceNode] = INF;
    q.push(sourceNode);
    inQueue[sourceNode] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inQueue[u] = false;

        for (int i = nodeHead[u]; ~i; i = edgeList[i].next) {
            int v = edgeList[i].to;
            int cap = edgeList[i].capacity;
            int cost = edgeList[i].cost;

            if (cap > 0 && distance[v] > distance[u] + cost) {
                distance[v] = distance[u] + cost;
                minFlow[v] = min(minFlow[u], cap);
                parentVertex[v] = u;
                parentEdge[v] = i;
                if (!inQueue[v]) {
                    q.push(v);
                    inQueue[v] = true;
                }
            }
        }
    }

    return parentVertex[sinkNode] != -1;
}

int totalFlow, minCost;

void minCostMaxFlow() {
    while (spfa()) {
        int flowAmount = minFlow[sinkNode];
        totalFlow += flowAmount;
        minCost += flowAmount * distance[sinkNode];

        int current = sinkNode;
        while (current != sourceNode) {
            edgeList[parentEdge[current]].capacity -= flowAmount;
            edgeList[parentEdge[current] ^ 1].capacity += flowAmount;
            current = parentVertex[current];
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    readInt(n); readInt(m); readInt(k); readInt(c); readInt(d);

    int B = max(n, k);
    sourceNode = n * (2 * B + 1) + 1;
    sinkNode = sourceNode + 1;

    distance.resize(sinkNode + 1);
    minFlow.resize(sinkNode + 1);
    parentVertex.resize(sinkNode + 1);
    parentEdge.resize(sinkNode + 1);
    inQueue.resize(sinkNode + 1);
    nodeHead.assign(sinkNode + 1, -1);

    for (int i = 0; i < k; i++) {
        int x;
        readInt(x);
        addEdge(sourceNode, x, 1, 0);
    }

    addEdge(n * (2 * B) + 1, sinkNode, INF, 0);

    for (int layer = 0; layer < 2 * B; layer++) {
        addEdge(layer * n + 1, (layer + 1) * n + 1, INF, 0);
        for (int i = 2; i <= n; i++) {
            addEdge(layer * n + i, (layer + 1) * n + i, INF, c);
        }
    }

    for (int i = 0; i < m; i++) {
        int x, y;
        readInt(x); readInt(y);
        for (int layer = 0; layer < 2 * B; layer++) {
            for (int j = 1; j <= k; j++) {
                int cost = d * (2 * j - 1) + c;
                addEdge(layer * n + x, (layer + 1) * n + y, 1, cost);
                addEdge(layer * n + y, (layer + 1) * n + x, 1, cost);
            }
        }
    }

    minCostMaxFlow();
    writeln(minCost);

    return 0;
}
